import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { randomUUID } from 'node:crypto';

const dir = dirname(fileURLToPath(import.meta.url));
const todosPath = join(dir, 'todos.json');

async function readTodos() {
  try {
    const data = await readFile(todosPath, 'utf8');
    const parsed = JSON.parse(data);
    return Array.isArray(parsed) ? parsed : [];
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

async function addTodo(text) {
  const todos = await readTodos();
  todos.push({ id: randomUUID(), text });
  await writeFile(todosPath, JSON.stringify(todos, null, 2) + '\n', 'utf8');
  console.log(`Added: ${text}`);
}

const [command, ...args] = process.argv.slice(2);

if (command === 'add' && args.length > 0) {
  await addTodo(args.join(' '));
} else {
  console.error('Usage: node index.js add "<text>"');
  process.exitCode = 1;
}

