async function doneTodo(n) {
  const todos = await readTodos();
  const index = Number(n) - 1; // 序号从 1 开始
  if (!Number.isInteger(index) || index < 0 || index >= todos.length) {
    console.error(`Invalid index: ${n}`);
    process.exitCode = 1;
    return;
  }
  todos[index].done = true;
  await writeFile(todosPath, JSON.stringify(todos, null, 2) + '\n', 'utf8');
  console.log(`Done: ${todos[index].text}`);
}

const [command, ...args] = process.argv.slice(2);

if (command === 'add' && args.length > 0) {
  await addTodo(args.join(' '));
} else if (command === 'list') {
  await listTodos();
} else if (command === 'done' && args.length === 1) {
  await doneTodo(args[0]);
} else {
  console.error('Usage: node index.js add "<text>" | list | done <序号>');
  process.exitCode = 1;
}

