async function clearTodos() {
  const todos = await readTodos();
  const remaining = todos.filter((todo) => todo.done !== true);
  const removed = todos.length - remaining.length;
  await writeFile(todosPath, JSON.stringify(remaining, null, 2) + '\n', 'utf8');
  console.log(`Cleared: ${removed}`);
}

const [command, ...args] = process.argv.slice(2);

